(window.CARDS = window.CARDS || {}).city = [{"name":"Париж","emoji":"🥖","meta":["Франция","около 2,1 млн"],"description":"Столица Франции раскинулась по берегам Сены и веками остаётся символом романтики и высокой моды. Эйфелева башня, Лувр и Нотр-Дам ежегодно притягивают миллионы туристов со всего мира.","fact":"Эйфелеву башню строили как временную конструкцию для выставки 1889 года и планировали снести спустя двадцать лет.","wiki_en":"Paris"},{"name":"Лондон","emoji":"🎡","meta":["Великобритания","около 9 млн"],"description":"Столица Великобритании стоит на Темзе и сочетает вековые традиции монархии с ролью крупнейшего финансового центра Европы. Биг-Бен, Тауэрский мост и красные двухэтажные автобусы узнаваемы по всему миру.","fact":"Название Биг-Бен изначально относилось только к самому колоколу башни, а не ко всей башне целиком.","wiki_en":"London"},{"name":"Нью-Йорк","emoji":"🗽","meta":["США","около 8,3 млн"],"description":"Крупнейший город США состоит из пяти районов и совмещает небоскрёбы Манхэттена с Центральным парком и берегами трёх рек. Здесь находятся Уолл-стрит, Бродвей и статуя Свободы — символы американской мечты.","fact":"Нью-Йорк прозвали Большим яблоком ещё в 1920-х годах — так его называли жокеи на ипподромах.","wiki_en":"New York City"},{"name":"Токио","emoji":"🗼","meta":["Япония","около 14 млн"],"description":"Столица Японии — один из самых густонаселённых мегаполисов мира, где небоскрёбы соседствуют с синтоистскими храмами и цветущей сакурой. Токио славится высокими технологиями, суши и оживлённым перекрёстком Сибуя.","fact":"Перекрёсток Сибуя в Токио считается одним из самых оживлённых пешеходных перекрёстков в мире.","wiki_en":"Tokyo"},{"name":"Рим","emoji":"🏛️","meta":["Италия","около 2,8 млн"],"description":"Вечный город на семи холмах был центром Римской империи и остаётся сокровищницей античной и христианской архитектуры. Колизей, Пантеон и Ватикан делают его одним из самых посещаемых городов мира.","fact":"По легенде, путешественник, бросивший монету в фонтан Треви, обязательно вернётся в Рим.","wiki_en":"Rome"},{"name":"Барселона","emoji":"🦎","meta":["Испания","около 1,6 млн"],"description":"Столица Каталонии на побережье Средиземного моря знаменита фантазийной архитектурой Антонио Гауди, включая недостроенный храм Саграда Фамилия. Город также известен футбольным клубом «Барселона» и широким бульваром Рамбла.","fact":"Храм Саграда Фамилия строится уже более ста сорока лет и до сих пор не завершён.","wiki_en":"Barcelona"},{"name":"Мадрид","emoji":"🐻","meta":["Испания","около 3,3 млн"],"description":"Столица Испании в самом центре страны славится музеем Прадо, королевским дворцом и оживлённой ночной жизнью. Символом города считается медведь, тянущийся к земляничному дереву, изображённый на гербе.","fact":"Герб Мадрида с медведем и земляничным деревом можно увидеть в виде скульптуры на площади Пуэрта-дель-Соль.","wiki_en":"Madrid"},{"name":"Берлин","emoji":"🧱","meta":["Германия","около 3,7 млн"],"description":"Столица Германии пережила разделение на Восточный и Западный Берлин и падение стены в 1989 году, что сделало город символом воссоединения страны. Сегодня это центр современного искусства, стрит-арта и техно-клубов.","fact":"Небольшие участки Берлинской стены сохранены как памятник и разрисованы художниками со всего мира.","wiki_en":"Berlin"},{"name":"Амстердам","emoji":"🚲","meta":["Нидерланды","около 900 тыс"],"description":"Столица Нидерландов построена на сети каналов и известна велосипедной культурой, узкими домами вдоль воды и музеями Ван Гога и Рейксмузеум. Количество велосипедов здесь превышает число жителей.","fact":"В каналах Амстердама ежегодно находят тысячи велосипедов, упавших туда случайно или брошенных.","wiki_en":"Amsterdam"},{"name":"Прага","emoji":"🕰️","meta":["Чехия","около 1,3 млн"],"description":"Столица Чехии на берегах Влтавы сохранила средневековый облик со шпилями готических соборов и черепичными крышами. Пражский Град и Карлов мост делают её одним из самых атмосферных городов Европы.","fact":"Пражские куранты на Староместской площади — старейшие в мире астрономические часы, всё ещё работающие.","wiki_en":"Prague"},{"name":"Вена","emoji":"🎻","meta":["Австрия","около 1,9 млн"],"description":"Столица Австрии на протяжении веков была центром музыки и монархии Габсбургов, здесь жили и творили Моцарт, Бетховен и Штраус. Город известен кофейнями, оперой и дворцом Шёнбрунн.","fact":"В венских кофейнях по традиции можно часами сидеть над одной чашкой кофе, читая выложенные для гостей газеты.","wiki_en":"Vienna"},{"name":"Будапешт","emoji":"♨️","meta":["Венгрия","около 1,7 млн"],"description":"Столица Венгрии образована слиянием Буды и Пешта на разных берегах Дуная и славится термальными купальнями на натуральных горячих источниках. Здание парламента на набережной — одно из самых узнаваемых в Европе.","fact":"Купальни Сечени в Будапеште питаются природными термальными источниками и работают уже больше ста лет.","wiki_en":"Budapest"},{"name":"Стамбул","emoji":"🕌","meta":["Турция","около 15 млн"],"description":"Крупнейший город мира, раскинувшийся сразу на двух континентах, разделён проливом Босфор на европейскую и азиатскую части. Стамбул веками был столицей Византии и Османской империи, о чём напоминают собор Святой Софии и Голубая мечеть.","fact":"Собор Святой Софии за свою историю успел побывать и церковью, и мечетью, и музеем, и снова мечетью.","wiki_en":"Istanbul"},{"name":"Дубай","emoji":"🏙️","meta":["ОАЭ","около 3,5 млн"],"description":"Крупнейший город ОАЭ вырос из скромного порта в один из символов роскоши и футуристической архитектуры Персидского залива. Здесь находится Бурдж-Халифа — самое высокое здание в мире, и искусственные острова Пальм-Джумейра.","fact":"Бурдж-Халифа настолько высока, что на её верхних этажах солнце садится на несколько минут позже, чем у подножия.","wiki_en":"Dubai"},{"name":"Москва","emoji":"🏰","meta":["Россия","около 13 млн"],"description":"Столица России — крупнейший город страны с многовековой историей, сердцем которого остаётся Кремль с его соборами и Красная площадь. Здесь сочетаются купола собора Василия Блаженного и небоскрёбы делового центра Москва-Сити.","fact":"Московское метро славится станциями с мрамором, мозаиками и люстрами, задуманными как подземные дворцы для народа.","wiki_en":"Moscow"},{"name":"Санкт-Петербург","emoji":"🎭","meta":["Россия","около 5,4 млн"],"description":"Город на Неве основан Петром I как окно в Европу и стал одной из культурных столиц мира благодаря Эрмитажу, разводным мостам и дворцовым ансамблям. Летом здесь наступают знаменитые белые ночи.","fact":"Во время белых ночей в Санкт-Петербурге солнце почти не заходит, и город остаётся светлым до глубокой ночи.","wiki_en":"Saint Petersburg"},{"name":"Лос-Анджелес","emoji":"🎬","meta":["США","около 3,9 млн"],"description":"Крупнейший город Калифорнии — мировая столица кино и шоу-бизнеса благодаря району Голливуд и его знаменитой надписи на холмах. Здесь же находятся пляжи Санта-Моники и студии крупнейших киностудий.","fact":"Надпись HOLLYWOOD на холмах изначально была рекламой недвижимости и гласила HOLLYWOODLAND.","wiki_en":"Los Angeles"},{"name":"Сан-Франциско","emoji":"🌉","meta":["США","около 870 тыс"],"description":"Город на холмах Калифорнии знаменит мостом Золотые Ворота, канатными трамвайчиками и бывшей тюрьмой Алькатрас на острове в заливе. Неподалёку от города зародилась Кремниевая долина.","fact":"Мост Золотые Ворота выкрашен в оранжевый цвет для лучшей видимости в частых для города туманах.","wiki_en":"San Francisco"},{"name":"Лас-Вегас","emoji":"🎰","meta":["США","около 650 тыс"],"description":"Город в пустыне Невада вырос вокруг казино и превратился в мировую столицу азартных развлечений и ярких шоу. Знаменитый бульвар Стрип с его отелями-тематическими парками виден даже из космоса ночью.","fact":"В Лас-Вегасе можно пожениться прямо ночью в одной из многочисленных круглосуточных часовен.","wiki_en":"Las Vegas"},{"name":"Чикаго","emoji":"🌆","meta":["США","около 2,7 млн"],"description":"Крупнейший город Среднего Запада США стоит на берегу озера Мичиган и считается родиной современного небоскрёба. Архитектурные круизы по реке Чикаго и башня Уиллис-тауэр привлекают ценителей высотного строительства.","fact":"Реку Чикаго раз в год красят в ярко-зелёный цвет в честь Дня святого Патрика.","wiki_en":"Chicago"},{"name":"Майами","emoji":"🏖️","meta":["США","около 450 тыс"],"description":"Курортный город на юге Флориды известен пляжами Майами-Бич, пастельной архитектурой ар-деко и сильным латиноамериканским влиянием. Это популярное направление для отдыха и один из крупнейших портов для круизных лайнеров.","fact":"Район Саут-Бич в Майами обладает одним из крупнейших в мире собраний зданий в стиле ар-деко.","wiki_en":"Miami"},{"name":"Вашингтон","emoji":"🏛️","meta":["США","около 700 тыс"],"description":"Столица Соединённых Штатов спроектирована как отдельный федеральный округ и застроена монументальными зданиями власти. Белый дом, Капитолий и мемориалы на Национальной аллее делают город символом американской политики.","fact":"Высота зданий в Вашингтоне ограничена законом, поэтому в городе почти нет небоскрёбов и сохраняется низкий силуэт.","wiki_en":"Washington, D.C."},{"name":"Бостон","emoji":"🎓","meta":["США","около 650 тыс"],"description":"Один из старейших городов США сыграл ключевую роль в Войне за независимость и остаётся крупным научным центром благодаря соседним Гарварду и MIT. Исторические кварталы и Тропа свободы напоминают о революционном прошлом.","fact":"Бостонское чаепитие 1773 года, ставшее прологом к Войне за независимость, произошло именно в местной гавани.","wiki_en":"Boston"},{"name":"Сиэтл","emoji":"☕","meta":["США","около 750 тыс"],"description":"Портовый город на северо-западе США известен башней Спейс-Нидл, дождливым климатом и тем, что здесь зародилась сеть кофеен Starbucks. Город также стал родиной гранжа и таких музыкантов, как Nirvana.","fact":"Сеть Starbucks зародилась в Сиэтле в 1971 году, а её кофейня на рынке Пайк-Плейс работает до сих пор.","wiki_en":"Seattle"},{"name":"Новый Орлеан","emoji":"🎷","meta":["США","около 380 тыс"],"description":"Город на юге Луизианы с французскими и креольскими корнями считается родиной джаза и знаменит ежегодным карнавалом Марди Гра. Французский квартал с коваными балконами и уличной музыкой задаёт неповторимую атмосферу.","fact":"Джаз как музыкальный стиль сформировался именно в Новом Орлеане на рубеже XIX и XX веков.","wiki_en":"New Orleans"},{"name":"Хьюстон","emoji":"🚀","meta":["США","около 2,3 млн"],"description":"Крупнейший город Техаса вырос на нефтяной промышленности и стал домом для Космического центра имени Джонсона, откуда велось управление полётами NASA. Это один из самых многонациональных городов США.","fact":"Знаменитая фраза «Хьюстон, у нас проблема» связана именно с Центром управления полётами NASA в этом городе.","wiki_en":"Houston"},{"name":"Даллас","emoji":"🤠","meta":["США","около 1,3 млн"],"description":"Город на севере Техаса вырос из торгового поста в крупный деловой центр и известен ковбойской культурой и футбольной командой «Даллас Ковбойз». Здесь же в 1963 году был убит президент Джон Кеннеди.","fact":"Убийство президента Кеннеди в Далласе в 1963 году произошло на площади, которая сегодня носит название Дили-Плаза.","wiki_en":"Dallas"},{"name":"Филадельфия","emoji":"🔔","meta":["США","около 1,6 млн"],"description":"Один из старейших городов США был местом подписания Декларации независимости и одно время служил столицей страны. Здесь хранится треснувший Колокол свободы — символ американской независимости.","fact":"Колокол свободы в Филадельфии из-за большой трещины давно не звонят — его сохраняют как историческую реликвию.","wiki_en":"Philadelphia"},{"name":"Атланта","emoji":"🍑","meta":["США","около 500 тыс"],"description":"Столица штата Джорджия известна как родина Мартина Лютера Кинга и один из крупнейших транспортных узлов юга США. Атланту также называют городом персиков за её символ и обилие одноимённых улиц.","fact":"Аэропорт Атланты много лет подряд остаётся одним из самых загруженных аэропортов мира по пассажиропотоку.","wiki_en":"Atlanta"},{"name":"Денвер","emoji":"🏔️","meta":["США","около 715 тыс"],"description":"Столица Колорадо расположена на высоте ровно одной мили над уровнем моря, за что получила прозвище «Милевысокий город». Отсюда рукой подать до горнолыжных курортов Скалистых гор.","fact":"Одна из ступеней Капитолия штата в Денвере отмечена особой меткой на высоте ровно одной мили над уровнем моря.","wiki_en":"Denver"},{"name":"Сан-Диего","emoji":"🐬","meta":["США","около 1,4 млн"],"description":"Портовый город на юге Калифорнии у границы с Мексикой славится мягким климатом, пляжами и одним из крупнейших зоопарков мира. Здесь же ежегодно проходит культовый фестиваль поп-культуры Comic-Con.","fact":"Фестиваль Comic-Con, ежегодно проходящий в Сан-Диего, собирает более ста тысяч поклонников комиксов и кино.","wiki_en":"San Diego"},{"name":"Нэшвилл","emoji":"🎸","meta":["США","около 690 тыс"],"description":"Столица Теннесси считается мировой столицей музыки кантри и домом легендарного концертного зала Grand Ole Opry. Улицы центра города заполнены барами с живой музыкой почти круглые сутки.","fact":"Радиопрограмма Grand Ole Opry выходит в эфир из Нэшвилла с 1925 года и стала лицом музыки кантри.","wiki_en":"Nashville"},{"name":"Остин","emoji":"🎤","meta":["США","около 1 млн"],"description":"Столица Техаса известна как крупный центр живой музыки и технологического бизнеса, а также ежегодным фестивалем South by Southwest. Девиз города Keep Austin Weird отражает его творческую и независимую атмосферу.","fact":"Лозунг Keep Austin Weird родился как поддержка местных независимых магазинов в споре с крупными сетями.","wiki_en":"Austin, Texas"},{"name":"Детройт","emoji":"🚗","meta":["США","около 630 тыс"],"description":"Город в штате Мичиган называют колыбелью американского автопрома — именно здесь Генри Форд наладил массовое производство автомобилей. Детройт также известен как родина звукозаписывающей студии Motown.","fact":"Именно на заводах Форда в Детройте впервые применили конвейерную сборку автомобилей в промышленных масштабах.","wiki_en":"Detroit"},{"name":"Гонолулу","emoji":"🌺","meta":["США","около 350 тыс"],"description":"Столица Гавайев расположена на острове Оаху и знаменита пляжем Вайкики и мемориалом Пёрл-Харбор. Мягкий тропический климат делает город одним из главных курортов США.","fact":"Нападение на Пёрл-Харбор в 1941 году произошло в гавани неподалёку от центра Гонолулу.","wiki_en":"Honolulu"},{"name":"Торонто","emoji":"🍁","meta":["Канада","около 2,9 млн"],"description":"Крупнейший город Канады и финансовая столица страны знаменит башней Си-Эн-Тауэр, которая долгое время была самым высоким сооружением в мире. Это один из самых многонациональных городов планеты.","fact":"Башня Си-Эн-Тауэр в Торонто больше тридцати лет удерживала титул самого высокого отдельно стоящего сооружения мира.","wiki_en":"Toronto"},{"name":"Ванкувер","emoji":"🏔️","meta":["Канада","около 660 тыс"],"description":"Портовый город на западном побережье Канады окружён горами и океаном и регулярно признаётся одним из самых комфортных для жизни городов мира. В 2010 году здесь прошли зимние Олимпийские игры.","fact":"Ванкувер неоднократно занимал верхние строчки мировых рейтингов качества жизни благодаря природе и мягкому климату.","wiki_en":"Vancouver"},{"name":"Монреаль","emoji":"🎷","meta":["Канада","около 1,8 млн"],"description":"Крупнейший франкоязычный город Северной Америки за пределами Франции сочетает европейский шарм старых кварталов с оживлённой студенческой жизнью. Здесь ежегодно проходит один из крупнейших джазовых фестивалей мира.","fact":"Монреальский джазовый фестиваль входит в Книгу рекордов Гиннесса как крупнейший джазовый фестиваль в мире.","wiki_en":"Montreal"},{"name":"Мехико","emoji":"🌮","meta":["Мексика","около 9,2 млн"],"description":"Столица Мексики построена на месте древней ацтекской столицы Теночтитлан и сегодня является одним из крупнейших мегаполисов мира. Город славится богатой уличной кухней и обилием музеев.","fact":"Мехико постепенно погружается под землю, так как построен на осушенном озере, некогда окружавшем Теночтитлан.","wiki_en":"Mexico City"},{"name":"Канкун","emoji":"🏝️","meta":["Мексика","около 900 тыс"],"description":"Курортный город на полуострове Юкатан вырос из рыбацкой деревни в один из главных пляжных курортов Карибского моря. Неподалёку расположены руины древних городов майя, привлекающие любителей истории.","fact":"Ещё в 1970 году на месте Канкуна почти никто не жил — курорт был построен правительством Мексики с нуля.","wiki_en":"Cancún"},{"name":"Гавана","emoji":"🚘","meta":["Куба","около 2,1 млн"],"description":"Столица Кубы на берегу Карибского моря знаменита колониальной архитектурой Старой Гаваны, ромом и сохранившимся до наших дней парком классических американских автомобилей середины XX века. Набережная Малекон — главное место встреч горожан.","fact":"По улицам Гаваны до сих пор ездят тысячи американских автомобилей 1950-х годов, сохранённых благодаря многолетнему эмбарго.","wiki_en":"Havana"},{"name":"Рио-де-Жанейро","emoji":"🥁","meta":["Бразилия","около 6,7 млн"],"description":"Город у подножия горы Корковаду знаменит статуей Христа-Искупителя, пляжами Копакабана и Ипанема и самым ярким карнавалом в мире. Самба и футбол давно стали частью его культурной идентичности.","fact":"Статуя Христа-Искупителя возвышается на горе Корковаду почти в семистах метрах над городом и видна из многих его районов.","wiki_en":"Rio de Janeiro"},{"name":"Сан-Паулу","emoji":"🌇","meta":["Бразилия","около 12 млн"],"description":"Крупнейший город Южного полушария — деловая и промышленная столица Бразилии с одним из самых узнаваемых небоскрёбных силуэтов континента. Здесь проживает крупная итальянская и японская диаспора.","fact":"В районе Либердаде в Сан-Паулу живёт одна из крупнейших японских общин за пределами Японии.","wiki_en":"São Paulo"},{"name":"Буэнос-Айрес","emoji":"💃","meta":["Аргентина","около 3 млн"],"description":"Столица Аргентины на берегу Ла-Платы считается родиной танго и славится европейской архитектурой центральных проспектов. Район Ла-Бока с его цветными домами — один из самых фотографируемых уголков города.","fact":"Танго зародилось в портовых кварталах Буэнос-Айреса в конце XIX века среди иммигрантов и рабочих.","wiki_en":"Buenos Aires"},{"name":"Лима","emoji":"🥘","meta":["Перу","около 10 млн"],"description":"Столица Перу на побережье Тихого океана была основана испанцами как центр колониальной власти в Южной Америке и сохранила богатое историческое ядро. Сегодня Лима также считается одной из гастрономических столиц мира.","fact":"Несколько ресторанов Лимы регулярно входят в списки лучших ресторанов мира по версии международных рейтингов.","wiki_en":"Lima"},{"name":"Куско","emoji":"🦙","meta":["Перу","около 430 тыс"],"description":"Древняя столица империи инков в высокогорьях Анд служит отправной точкой для путешествий к Мачу-Пикчу. На улицах города до сих пор видны массивные каменные кладки, оставшиеся от инкских построек.","fact":"Каменные блоки инкской кладки в Куско пригнаны друг к другу настолько плотно, что между ними не проходит лезвие ножа.","wiki_en":"Cusco"},{"name":"Сантьяго","emoji":"🍷","meta":["Чили","около 6 млн"],"description":"Столица Чили расположена в долине у подножия Анд, чьи заснеженные вершины видны прямо из центра города. Регион вокруг Сантьяго — один из крупнейших производителей вина в Южном полушарии.","fact":"Горнолыжные курорты Анд находятся всего в нескольких десятках километров от центра Сантьяго.","wiki_en":"Santiago"},{"name":"Монтевидео","emoji":"⚽","meta":["Уругвай","около 1,3 млн"],"description":"Столица Уругвая на берегу Ла-Платы известна протяжённой набережной Рамбла и стадионом Сентенарио, где прошёл первый в истории чемпионат мира по футболу. Город сохраняет спокойный и уютный характер в сравнении с соседними мегаполисами.","fact":"Стадион Сентенарио в Монтевидео был построен специально к первому чемпионату мира по футболу в 1930 году.","wiki_en":"Montevideo"},{"name":"Сидней","emoji":"⛵","meta":["Австралия","около 5,3 млн"],"description":"Крупнейший город Австралии знаменит зданием оперы с крышей в виде парусов и гаванью Порт-Джексон с одним из самых узнаваемых мостов мира. Пляж Бонди — один из самых известных городских пляжей планеты.","fact":"Крыша Сиднейского оперного театра состоит из более чем миллиона керамических плиток.","wiki_en":"Sydney"},{"name":"Мельбурн","emoji":"🎨","meta":["Австралия","около 5 млн"],"description":"Второй по величине город Австралии известен лабиринтами узких переулков с уличным искусством и кофейнями, а также статусом спортивной столицы страны. Здесь проходит этап Формулы-1 и Открытый чемпионат Австралии по теннису.","fact":"Мельбурн много лет подряд признавался одним из самых комфортных для жизни городов мира по международным рейтингам.","wiki_en":"Melbourne"},{"name":"Окленд","emoji":"🌋","meta":["Новая Зеландия","около 1,7 млн"],"description":"Крупнейший город Новой Зеландии раскинулся среди десятков потухших вулканических конусов и двух гаваней на противоположных берегах узкого перешейка. Обилие яхт в местных маринах дало городу прозвище «Город парусов».","fact":"Окленд прозвали «Городом парусов» из-за одного из самых высоких показателей числа яхт на душу населения в мире.","wiki_en":"Auckland"},{"name":"Гонконг","emoji":"🚢","meta":["Китай","около 7,4 млн"],"description":"Бывшая британская колония на юге Китая — один из ведущих финансовых центров Азии с одной из самых плотных застроек небоскрёбами в мире. Гавань Виктория и трамваи на пик Виктория — визитные карточки города.","fact":"Гонконг обладает одним из самых высоких показателей числа небоскрёбов на квадратный километр среди городов мира.","wiki_en":"Hong Kong"},{"name":"Макао","emoji":"🎲","meta":["Китай","около 680 тыс"],"description":"Бывшая португальская колония на юге Китая давно обогнала Лас-Вегас по доходам от казино и известна как азиатский Монте-Карло. В историческом центре сохранились колониальные португальские здания и мощёные улочки.","fact":"Доходы казино Макао уже много лет превышают доходы игорной индустрии Лас-Вегаса в несколько раз.","wiki_en":"Macau"},{"name":"Сингапур","emoji":"🦁","meta":["Сингапур","около 5,9 млн"],"description":"Город-государство на юге Малаккского полуострова превратился из скромного порта в один из самых богатых и технологичных мегаполисов мира. Символ города — статуя Мерлион с головой льва и телом рыбы.","fact":"Название «Сингапур» происходит от санскритских слов, означающих город льва.","wiki_en":"Singapore"},{"name":"Бангкок","emoji":"🛺","meta":["Таиланд","около 8 млн"],"description":"Столица Таиланда сочетает золочёные буддийские храмы и королевские дворцы с оживлёнными рынками и ночной жизнью. По каналам-клонгам до сих пор курсируют лодки, за что город когда-то называли восточной Венецией.","fact":"Полное церемониальное название Бангкока — одно из самых длинных названий городов в мире и занесено в Книгу рекордов Гиннесса.","wiki_en":"Bangkok"},{"name":"Сеул","emoji":"🎶","meta":["Республика Корея","около 9,7 млн"],"description":"Столица Южной Кореи выросла из древней столицы династии Чосон в один из самых технологичных мегаполисов мира и центр мировой поп-культуры K-pop. Дворец Кёнбоккун соседствует с небоскрёбами района Каннам.","fact":"Название района Каннам стало известно во всём мире благодаря песне Gangnam Style.","wiki_en":"Seoul"},{"name":"Пекин","emoji":"🏯","meta":["Китай","около 21 млн"],"description":"Столица Китая многие века служила резиденцией императоров, о чём напоминает Запретный город в самом центре мегаполиса. Неподалёку от города проходит участок Великой Китайской стены.","fact":"Запретный город в Пекине насчитывает почти тысячу зданий и был закрыт для простых людей на протяжении столетий.","wiki_en":"Beijing"},{"name":"Шанхай","emoji":"🌃","meta":["Китай","около 24 млн"],"description":"Крупнейший город Китая на берегу реки Хуанпу — один из ведущих финансовых центров мира с футуристическим силуэтом района Пудун. Набережная Бунд сохраняет колониальную архитектуру начала XX века напротив небоскрёбов.","fact":"Всего за несколько десятилетий бывшие рисовые поля района Пудун в Шанхае превратились в лес небоскрёбов.","wiki_en":"Shanghai"},{"name":"Шэньчжэнь","emoji":"💻","meta":["Китай","около 17,5 млн"],"description":"Город на границе с Гонконгом всего за несколько десятилетий превратился из рыбацкой деревни в один из мировых центров электронной промышленности. Его стремительный рост стал символом экономических реформ Китая.","fact":"Ещё в конце 1970-х годов на месте Шэньчжэня было небольшое рыбацкое поселение с населением в несколько десятков тысяч человек.","wiki_en":"Shenzhen"},{"name":"Тайбэй","emoji":"🧋","meta":["Тайвань","около 2,6 млн"],"description":"Столица Тайваня известна ночными рынками с уличной едой, чайной культурой и небоскрёбом Тайбэй 101, который несколько лет удерживал титул самого высокого здания в мире. Плотную городскую застройку со всех сторон обступают зелёные горы.","fact":"Внутри небоскрёба Тайбэй 101 подвешен огромный стальной шар, который гасит колебания здания при тайфунах и землетрясениях.","wiki_en":"Taipei"},{"name":"Киото","emoji":"⛩️","meta":["Япония","около 1,5 млн"],"description":"Бывшая императорская столица Японии сохранила тысячи буддийских храмов и синтоистских святилищ, включая знаменитые красные ворота-тории Фусими Инари. Исторические кварталы гейш придают городу особую атмосферу старой Японии.","fact":"В Киото около двух тысяч буддийских храмов и синтоистских святилищ, а часть из них включена в список Всемирного наследия ЮНЕСКО.","wiki_en":"Kyoto"},{"name":"Осака","emoji":"🐙","meta":["Япония","около 2,7 млн"],"description":"Третий по величине город Японии славится уличной едой, включая шарики такояки с осьминогом, и оживлённым районом Дотонбори с яркими неоновыми вывесками. Осакский замок остаётся одним из символов города.","fact":"Гигантская светящаяся вывеска краба над рестораном в квартале Дотонбори стала одним из самых узнаваемых символов Осаки.","wiki_en":"Osaka"},{"name":"Дели","emoji":"🪔","meta":["Индия","более 15 млн"],"description":"Столица Индии объединяет древний исторический центр с памятниками эпохи Моголов, включая гробницу Хумаюна, и современный правительственный квартал Нью-Дели. Это один из самых густонаселённых городских регионов мира.","fact":"Ворота Индии в Дели построены как памятник погибшим солдатам, служившим в британской индийской армии.","wiki_en":"Delhi"},{"name":"Мумбаи","emoji":"🎞️","meta":["Индия","около 12,5 млн"],"description":"Финансовая столица Индии на западном побережье страны — один из самых густонаселённых городов мира и центр киноиндустрии Болливуд. Арка Ворота Индии на набережной и вокзал Чатрапати-Шиваджи в викторианском стиле — главные символы города.","fact":"Индия выпускает больше художественных фильмов в год, чем любая другая страна мира, и заметная часть съёмок проходит в Мумбаи.","wiki_en":"Mumbai"},{"name":"Катманду","emoji":"🙏","meta":["Непал","около 1,5 млн"],"description":"Столица Непала лежит в горной долине у подножия Гималаев и служит отправной точкой для восхождений на Эверест. Город сохранил множество древних буддийских ступ и индуистских храмов, включённых в список ЮНЕСКО.","fact":"Из Катманду начинаются практически все маршруты альпинистов, отправляющихся покорять Эверест.","wiki_en":"Kathmandu"},{"name":"Куала-Лумпур","emoji":"🏢","meta":["Малайзия","около 1,8 млн"],"description":"Столица Малайзии известна башнями-близнецами Петронас, которые долгое время были самыми высокими зданиями в мире, и смешением малайской, китайской и индийской культур. Город окружён тропическими джунглями.","fact":"Башни Петронас соединены мостом-переходом на уровне сорок первого этажа — одним из самых высоких двухэтажных мостов мира.","wiki_en":"Kuala Lumpur"},{"name":"Джакарта","emoji":"🛵","meta":["Индонезия","около 10,6 млн"],"description":"Столица Индонезии на острове Ява — один из крупнейших мегаполисов Юго-Восточной Азии, известный плотным движением мопедов и стремительным погружением земли под уровень моря. Власти страны уже начали перенос столицы на остров Калимантан.","fact":"Джакарта считается одним из самых быстро погружающихся городов мира, из-за чего Индонезия строит новую столицу на Калимантане.","wiki_en":"Jakarta"},{"name":"Манила","emoji":"⛪","meta":["Филиппины","около 1,8 млн"],"description":"Столица Филиппин на берегу Манильского залива сохранила испанский колониальный квартал Интрамурос с крепостными стенами и старинными церквями. Это один из самых густонаселённых городов мира по плотности застройки.","fact":"Район Интрамурос в Маниле был построен испанцами в XVI веке как укреплённый город внутри городских стен.","wiki_en":"Manila"},{"name":"Ханой","emoji":"🍜","meta":["Вьетнам","около 8,4 млн"],"description":"Столица Вьетнама сохранила французскую колониальную архитектуру и старинный квартал с узкими торговыми улочками вокруг Озера возвращённого меча. Уличная еда, включая суп фо, — важная часть повседневной жизни города.","fact":"По легенде, озеро Хоанкьем в центре Ханоя получило название после того, как гигантская черепаха забрала у императора волшебный меч.","wiki_en":"Hanoi"},{"name":"Хошимин","emoji":"🏍️","meta":["Вьетнам","около 9 млн"],"description":"Крупнейший город Вьетнама, прежде носивший название Сайгон, остаётся деловым и торговым центром страны с плотным потоком мотобайков на улицах. В городе сохранились здания французской колониальной эпохи, включая собор Нотр-Дам.","fact":"Город был переименован в Хошимин в 1976 году в честь вьетнамского революционного лидера, но многие жители по-прежнему называют его Сайгоном.","wiki_en":"Ho Chi Minh City"},{"name":"Каир","emoji":"🐫","meta":["Египет","около 10 млн"],"description":"Столица Египта на берегу Нила — крупнейший город арабского мира, у окраины которого возвышаются пирамиды Гизы и Большой Сфинкс. Средневековый исламский центр города включён в список Всемирного наследия ЮНЕСКО.","fact":"Пирамиды Гизы находятся не в пустыне посреди Каира, а на самой его окраине, почти вплотную к городской застройке.","wiki_en":"Cairo"},{"name":"Марракеш","emoji":"🛍️","meta":["Марокко","около 930 тыс"],"description":"Город у подножия Атласских гор известен лабиринтами базаров медины и оживлённой площадью Джемаа-эль-Фна с заклинателями змей и уличными музыкантами. Красноватый цвет глиняных построек дал городу прозвище «Красный город».","fact":"Марракеш прозвали «Красным городом» за характерный терракотовый цвет стен, в который традиционно окрашены здания старого центра.","wiki_en":"Marrakesh"},{"name":"Касабланка","emoji":"⚓","meta":["Марокко","около 3,4 млн"],"description":"Крупнейший город Марокко и главный экономический центр страны прославился благодаря одноимённому голливудскому фильму 1942 года, хотя большая часть картины снималась в павильонах США. Здесь находится одна из крупнейших мечетей мира — мечеть Хасана II.","fact":"Хотя фильм «Касабланка» прославил город на весь мир, снимался он почти целиком в студийных павильонах в Калифорнии.","wiki_en":"Casablanca"},{"name":"Кейптаун","emoji":"⛰️","meta":["ЮАР","около 4,7 млн"],"description":"Город на юго-западе ЮАР раскинулся у подножия плосковершинной Столовой горы на атлантическом побережье, недалеко от южной оконечности Африки. Неподалёку от берега расположен остров Роббен, где в тюрьме много лет провёл Нельсон Мандела.","fact":"Нельсон Мандела провёл значительную часть своего заключения в тюрьме на острове Роббен неподалёку от Кейптауна.","wiki_en":"Cape Town"},{"name":"Йоханнесбург","emoji":"⛏️","meta":["ЮАР","около 5,8 млн"],"description":"Крупнейший город ЮАР вырос в конце XIX века вокруг золотых приисков и остаётся главным деловым центром страны. Район Соуэто сыграл ключевую роль в истории борьбы против апартеида.","fact":"Йоханнесбург вырос буквально за несколько лет после открытия одного из крупнейших в мире месторождений золота в 1886 году.","wiki_en":"Johannesburg"},{"name":"Найроби","emoji":"🦒","meta":["Кения","около 4,4 млн"],"description":"Столица Кении — один из немногих крупных городов мира, у самой границы которого расположен настоящий национальный парк с дикими львами и жирафами. Найроби также служит штаб-квартирой нескольких агентств ООН.","fact":"Национальный парк Найроби находится в паре километров от небоскрёбов центра города, и на его фоне часто фотографируют жирафов и львов.","wiki_en":"Nairobi"},{"name":"Лагос","emoji":"🌊","meta":["Нигерия","более 15 млн"],"description":"Крупнейший город Нигерии и один из самых быстрорастущих мегаполисов Африки раскинулся на лагунах Атлантического побережья. Город считается центром нигерийской киноиндустрии Nollywood и оживлённой музыкальной сцены афробитов.","fact":"Нигерийская киноиндустрия Nollywood, во многом базирующаяся в Лагосе, — одна из крупнейших в мире по числу выпускаемых за год фильмов.","wiki_en":"Lagos"},{"name":"Иерусалим","emoji":"🕍","meta":["Израиль","около 950 тыс"],"description":"Один из древнейших городов мира почитается как святыня сразу тремя религиями — иудаизмом, христианством и исламом. Старый город со Стеной Плача, Храмом Гроба Господня и Куполом Скалы включён в список ЮНЕСКО.","fact":"Старый город Иерусалима традиционно делится на четыре квартала — еврейский, христианский, мусульманский и армянский.","wiki_en":"Jerusalem"},{"name":"Тель-Авив","emoji":"🕶️","meta":["Израиль","около 460 тыс"],"description":"Молодой город на средиземноморском побережье Израиля известен пляжами, насыщенной ночной жизнью и одним из крупнейших в мире собраний архитектуры в стиле баухаус. Город часто называют технологическим и стартап-центром страны.","fact":"Более четырёх тысяч зданий в стиле баухаус, построенных эмигрировавшими из Европы архитекторами, принесли Тель-Авиву прозвище «Белый город».","wiki_en":"Tel Aviv"},{"name":"Доха","emoji":"🏟️","meta":["Катар","около 1,2 млн"],"description":"Столица Катара на побережье Персидского залива стремительно превратилась из небольшого поселения ловцов жемчуга в город футуристических небоскрёбов. В 2022 году Доха и её окрестности принимали финал чемпионата мира по футболу.","fact":"Ещё в середине XX века экономика Дохи держалась на добыче жемчуга, прежде чем её сменили доходы от нефти и газа.","wiki_en":"Doha"},{"name":"Абу-Даби","emoji":"🏎️","meta":["ОАЭ","около 1,5 млн"],"description":"Столица ОАЭ на острове в Персидском заливе сочетает нефтяное богатство с амбициозными культурными проектами, включая филиал Лувра. Мечеть шейха Зайда с белоснежными куполами — одна из крупнейших в мире.","fact":"В мечети шейха Зайда в Абу-Даби постелен один из крупнейших в мире ковров ручной работы.","wiki_en":"Abu Dhabi"},{"name":"Эр-Рияд","emoji":"🏜️","meta":["Саудовская Аравия","около 7,5 млн"],"description":"Столица Саудовской Аравии в центре Аравийского полуострова быстро превращается из консервативного административного центра в мегаполис с амбициозными архитектурными проектами. Небоскрёб Кингдом-центр с аркой на вершине — один из символов города.","fact":"Вершину небоскрёба Кингдом-центр в Эр-Рияде венчает смотровой мост-перемычка на высоте около трёхсот метров.","wiki_en":"Riyadh"},{"name":"Тегеран","emoji":"🧿","meta":["Иран","около 9,3 млн"],"description":"Столица Ирана раскинулась у подножия заснеженных гор Эльбурс и остаётся крупнейшим городом страны и её культурным центром. В музеях города хранятся коллекции драгоценностей персидских шахов, включая знаменитый Павлиний трон.","fact":"В хранилище Центрального банка Ирана в Тегеране выставлена одна из самых богатых в мире коллекций драгоценностей.","wiki_en":"Tehran"},{"name":"Венеция","emoji":"🛶","meta":["Италия","около 260 тыс"],"description":"Город на лагуне Адриатического моря построен на сотне небольших островов, соединённых мостами и каналами вместо улиц. Площадь Сан-Марко и катание на гондолах остаются главными символами Венеции.","fact":"Во время сезонных наводнений acqua alta площадь Сан-Марко регулярно уходит под воду, и по ней прокладывают деревянные помосты.","wiki_en":"Venice"},{"name":"Флоренция","emoji":"🎨","meta":["Италия","около 360 тыс"],"description":"Столица итальянского региона Тоскана считается колыбелью эпохи Возрождения, здесь творили Микеланджело, Боттичелли и Леонардо да Винчи. Купол собора Санта-Мария-дель-Фьоре доминирует над панорамой города.","fact":"Статуя Давида работы Микеланджело изначально стояла под открытым небом на главной площади Флоренции.","wiki_en":"Florence"},{"name":"Милан","emoji":"👗","meta":["Италия","около 1,4 млн"],"description":"Деловая столица Италии считается одной из мировых столиц моды и дизайна, где дважды в год проходят недели высокой моды. Миланский собор Дуомо с его ажурными шпилями — одна из крупнейших готических церквей мира.","fact":"На строительство Миланского собора ушло почти шесть веков, прежде чем он был полностью завершён.","wiki_en":"Milan"},{"name":"Неаполь","emoji":"🍕","meta":["Италия","около 950 тыс"],"description":"Портовый город на юге Италии у подножия вулкана Везувий считается родиной классической пиццы маргарита. Неподалёку находятся руины Помпей, погибших при извержении вулкана почти две тысячи лет назад.","fact":"По преданию, пиццу маргарита назвали в честь королевы Маргариты Савойской, которой понравилось сочетание цветов итальянского флага.","wiki_en":"Naples"},{"name":"Лиссабон","emoji":"🚋","meta":["Португалия","около 550 тыс"],"description":"Столица Португалии раскинулась на семи холмах у устья реки Тежу и известна старинными жёлтыми трамваями, петляющими по узким улочкам. Меланхоличная музыка фаду родилась именно в тавернах этого города.","fact":"Музыкальный жанр фаду, включённый в список нематериального наследия ЮНЕСКО, зародился в портовых кварталах Лиссабона.","wiki_en":"Lisbon"},{"name":"Порту","emoji":"🍷","meta":["Португалия","около 230 тыс"],"description":"Второй по величине город Португалии дал имя портвейну — крепкому вину, которое веками выдерживают в погребах на берегу реки Дору. Исторический центр с разноцветными домами включён в список Всемирного наследия ЮНЕСКО.","fact":"Портвейн получил своё название именно от города Порту, откуда вино веками отправляли на экспорт по всему миру.","wiki_en":"Porto"},{"name":"Севилья","emoji":"🍊","meta":["Испания","около 690 тыс"],"description":"Столица испанской Андалусии считается родиной фламенко и славится грандиозным готическим собором с колокольней Хиральда, некогда бывшей минаретом мечети. Улицы старого центра обсажены апельсиновыми деревьями.","fact":"Севильский собор — крупнейший по объёму готический собор в мире, а его колокольня Хиральда изначально строилась как минарет.","wiki_en":"Seville"},{"name":"Валенсия","emoji":"🍚","meta":["Испания","около 800 тыс"],"description":"Портовый город на средиземноморском побережье Испании считается родиной паэльи и известен футуристическим комплексом Город искусств и наук. Исторический центр сочетается здесь с современными архитектурными формами Сантьяго Калатравы.","fact":"Классическая паэлья была придумана именно в окрестностях Валенсии как блюдо из риса, овощей и мяса.","wiki_en":"Valencia"},{"name":"Ницца","emoji":"🌴","meta":["Франция","около 340 тыс"],"description":"Главный курорт французской Ривьеры на Лазурном берегу известен набережной Променад-дез-Англе и галечными пляжами. Мягкий средиземноморский климат издавна привлекал сюда европейскую аристократию.","fact":"Набережная Променад-дез-Англе в Ницце была построена на средства английских аристократов, зимовавших на Лазурном берегу.","wiki_en":"Nice"},{"name":"Марсель","emoji":"⚓","meta":["Франция","около 870 тыс"],"description":"Старейший город Франции и её крупнейший порт на Средиземном море был основан греческими колонистами более двух тысяч лет назад. Рыбный суп буйабес считается традиционным блюдом марсельской кухни.","fact":"Марсель был основан греческими мореплавателями из Фокеи около двух с половиной тысяч лет назад.","wiki_en":"Marseille"},{"name":"Лион","emoji":"🍽️","meta":["Франция","около 520 тыс"],"description":"Город у слияния рек Рона и Сона считается гастрономической столицей Франции и родиной кинематографа: здесь работала фабрика братьев Люмьер и был снят их самый первый фильм. Старые кварталы знамениты скрытыми проходами-траболями.","fact":"Первый фильм братьев Люмьер снят у ворот их собственной фабрики в Лионе и показывает рабочих, выходящих после смены.","wiki_en":"Lyon"},{"name":"Монако","emoji":"💎","meta":["Монако","около 39 тыс"],"description":"Крошечное государство на Лазурном берегу известно казино Монте-Карло и ежегодной гонкой Формулы-1, которая проходит прямо по городским улицам. Это одна из самых маленьких и плотно застроенных стран мира.","fact":"Трасса Гран-при Монако проходит прямо по обычным городским улицам княжества, вдоль яхтенной гавани и через тоннель.","wiki_en":"Monaco"},{"name":"Брюссель","emoji":"🧇","meta":["Бельгия","около 1,2 млн"],"description":"Столица Бельгии и фактическая столица Европейского союза известна вафлями, шоколадом и пивными традициями, а также скульптурой Писающего мальчика. Центральная площадь Гран-Плас признана одной из красивейших в Европе.","fact":"Статую Писающего мальчика в Брюсселе время от времени наряжают в костюмы по случаю городских праздников.","wiki_en":"Brussels"},{"name":"Брюгге","emoji":"🚣","meta":["Бельгия","около 120 тыс"],"description":"Средневековый город на севере Бельгии прозвали северной Венецией за сеть каналов, пересекающих исторический центр. Мощёные улочки и кирпичные фасады домов сохранились практически в первозданном виде.","fact":"Исторический центр Брюгге настолько хорошо сохранился, что целиком включён в список Всемирного наследия ЮНЕСКО.","wiki_en":"Bruges"},{"name":"Мюнхен","emoji":"🍺","meta":["Германия","около 1,5 млн"],"description":"Столица Баварии известна во всём мире благодаря пивному фестивалю Октоберфест и футбольному клубу «Бавария». Центральная площадь Мариенплац с ратушей и курантами — сердце старого города.","fact":"Октоберфест в Мюнхене ежегодно собирает миллионы гостей и, несмотря на название, начинается ещё в сентябре.","wiki_en":"Munich"},{"name":"Гамбург","emoji":"⛴️","meta":["Германия","около 1,9 млн"],"description":"Крупнейший портовый город Германии на реке Эльбе известен кварталом красных фонарей Репербан, где в начале карьеры выступали The Beatles. Концертный зал Эльбфилармони с волнообразной крышей стал новым символом города.","fact":"Группа The Beatles провела важную часть своих ранних выступлений именно в клубах гамбургского квартала Репербан.","wiki_en":"Hamburg"},{"name":"Франкфурт-на-Майне","emoji":"🏦","meta":["Германия","около 760 тыс"],"description":"Финансовая столица Германии и место расположения Европейского центрального банка выделяется среди немецких городов необычно плотной застройкой небоскрёбами, за что её прозвали Майнхэттеном. Здесь же родился писатель Иоганн Вольфганг Гёте.","fact":"Силуэт Франкфурта с его высотными зданиями настолько нетипичен для Германии, что город прозвали Майнхэттеном по аналогии с Манхэттеном.","wiki_en":"Frankfurt"},{"name":"Кёльн","emoji":"⛪","meta":["Германия","около 1,1 млн"],"description":"Один из старейших городов Германии знаменит своим огромным готическим собором, шпили которого после завершения стройки несколько лет были самыми высокими в мире. Город также известен производством одеколона, давшего изделию его общее имя.","fact":"Кёльнский собор строился с перерывами более шестисот лет и был завершён только в XIX веке.","wiki_en":"Cologne"},{"name":"Цюрих","emoji":"🍫","meta":["Швейцария","около 440 тыс"],"description":"Крупнейший город Швейцарии на берегу одноимённого озера — один из ведущих мировых финансовых центров и неизменный лидер рейтингов качества жизни. Старый город Нидердорф сохранил средневековые узкие улочки.","fact":"Цюрих регулярно занимает верхние строчки международных рейтингов городов с самым высоким качеством жизни.","wiki_en":"Zurich"},{"name":"Женева","emoji":"⛲","meta":["Швейцария","около 205 тыс"],"description":"Город на берегу Женевского озера служит европейской штаб-квартирой ООН и домом для множества международных организаций. Фонтан Же-До, бьющий прямо из озера, виден практически из любой точки города.","fact":"Струя фонтана Же-До в Женеве поднимается на высоту более ста метров и видна за много километров от города.","wiki_en":"Geneva"},{"name":"Зальцбург","emoji":"🎼","meta":["Австрия","около 155 тыс"],"description":"Родной город Вольфганга Амадея Моцарта сохранил барочный исторический центр под старинной крепостью Хоэнзальцбург. Здесь же снимали значительную часть знаменитого фильма «Звуки музыки».","fact":"Дом, где родился Моцарт, в центре Зальцбурга превращён в музей и остаётся одной из главных достопримечательностей города.","wiki_en":"Salzburg"},{"name":"Копенгаген","emoji":"🧜","meta":["Дания","около 650 тыс"],"description":"Столица Дании на острове Зеландия известна цветными домиками набережной Нюхавн, велосипедной культурой и статуей Русалочки на берегу залива. Город регулярно признаётся одним из самых удобных для жизни в мире.","fact":"Статуя Русалочки в Копенгагене установлена в честь сказки Ганса Христиана Андерсена и стала символом города.","wiki_en":"Copenhagen"},{"name":"Стокгольм","emoji":"🛥️","meta":["Швеция","около 980 тыс"],"description":"Столица Швеции раскинулась сразу на полутора десятках островов, соединённых мостами, между озером Меларен и Балтийским морем. Старый город Гамла-стан сохранил средневековую планировку узких улочек.","fact":"Стокгольм часто называют северной Венецией за то, что он построен более чем на десятке островов.","wiki_en":"Stockholm"},{"name":"Осло","emoji":"⛷️","meta":["Норвегия","около 700 тыс"],"description":"Столица Норвегии расположена в глубине живописного Осло-фьорда и окружена лесистыми холмами, популярными для лыжных прогулок прямо из центра города. Здесь ежегодно вручают Нобелевскую премию мира.","fact":"Нобелевскую премию мира ежегодно вручают именно в Осло, тогда как остальные премии Нобеля вручают в Стокгольме.","wiki_en":"Oslo"},{"name":"Хельсинки","emoji":"🧖","meta":["Финляндия","около 660 тыс"],"description":"Столица Финляндии на берегу Балтийского моря известна строгой неоклассической архитектурой Сенатской площади и огромным числом саун на душу населения. Город регулярно занимает верхние строчки рейтингов качества жизни.","fact":"Сауны в Хельсинки встречаются и в обычных жилых домах, и в офисах, а общественные городские сауны снова стали модным местом встреч.","wiki_en":"Helsinki"},{"name":"Рейкьявик","emoji":"🌌","meta":["Исландия","около 140 тыс"],"description":"Самая северная столица мира служит отправной точкой для путешествий к гейзерам, ледникам и вулканам Исландии. Благодаря геотермальной энергии большая часть города отапливается природным теплом земли.","fact":"Почти все дома в Рейкьявике отапливаются геотермальной водой, поступающей прямо из недр земли.","wiki_en":"Reykjavík"},{"name":"Дублин","emoji":"🍀","meta":["Ирландия","около 550 тыс"],"description":"Столица Ирландии на берегу реки Лиффи — родина пива Guinness и писателей Джеймса Джойса и Оскара Уайльда. Оживлённый квартал Темпл-Бар известен пабами с живой ирландской музыкой.","fact":"Пивоварня Guinness в Дублине подписала в XVIII веке договор аренды земли сроком на девять тысяч лет.","wiki_en":"Dublin"},{"name":"Эдинбург","emoji":"🏴","meta":["Великобритания","около 530 тыс"],"description":"Столица Шотландии выросла вокруг древнего замка на вершине потухшего вулкана и ежегодно принимает крупнейший в мире фестиваль искусств Fringe. Средневековая Королевская миля соединяет замок с Холирудским дворцом.","fact":"Эдинбургский фестиваль Fringe считается крупнейшим в мире фестивалем искусств по числу показов и спектаклей.","wiki_en":"Edinburgh"},{"name":"Манчестер","emoji":"⚽","meta":["Великобритания","около 550 тыс"],"description":"Город на севере Англии стал колыбелью промышленной революции благодаря текстильным фабрикам, а сегодня известен как родина футбольных клубов «Манчестер Юнайтед» и «Манчестер Сити». Здесь же зародилась музыкальная сцена мадчестер конца 1980-х.","fact":"Манчестер считается местом, где в XVIII–XIX веках зародилась промышленная революция благодаря текстильным фабрикам.","wiki_en":"Manchester"},{"name":"Ливерпуль","emoji":"🎸","meta":["Великобритания","около 500 тыс"],"description":"Портовый город на северо-западе Англии знаменит прежде всего как родина группы The Beatles, чей путь к славе начинался в местном клубе Cavern. Кирпичные склады набережной Альберт-Док превращены в музейный и ресторанный квартал.","fact":"Клуб Cavern в Ливерпуле, где начинали The Beatles, был восстановлен после сноса и работает до сих пор недалеко от исторического места.","wiki_en":"Liverpool"},{"name":"Афины","emoji":"🦉","meta":["Греция","около 3,2 млн"],"description":"Столица Греции считается одной из колыбелей европейской цивилизации, философии и демократии. Над городом возвышается Акрополь с храмом Парфенон, построенным ещё в V веке до нашей эры.","fact":"Сова считалась священной птицей богини Афины и до сих пор остаётся неофициальным символом города.","wiki_en":"Athens"},{"name":"Дубровник","emoji":"🛡️","meta":["Хорватия","около 42 тыс"],"description":"Город-крепость на побережье Адриатики окружён мощными средневековыми стенами, по которым можно пройти вокруг всего старого города. Благодаря живописным улочкам Дубровник стал одной из основных съёмочных площадок сериала «Игра престолов».","fact":"Многие сцены Королевской Гавани в сериале «Игра престолов» снимались именно на улицах старого Дубровника.","wiki_en":"Dubrovnik"},{"name":"Сплит","emoji":"🏺","meta":["Хорватия","около 180 тыс"],"description":"Второй по величине город Хорватии вырос прямо внутри и вокруг древнеримского дворца императора Диоклетиана, построенного в начале IV века. Сегодня в бывших дворцовых стенах работают кафе, магазины и жилые дома.","fact":"Исторический центр Сплита фактически представляет собой сохранившийся дворец римского императора Диоклетиана, где до сих пор живут люди.","wiki_en":"Split, Croatia"},{"name":"Загреб","emoji":"🏘️","meta":["Хорватия","около 800 тыс"],"description":"Столица Хорватии делится на Верхний город с готическими соборами и мощёными площадями и более современный Нижний город с музеями и парками. Рождественские ярмарки Загреба неоднократно признавались лучшими в Европе.","fact":"Рождественский рынок Загреба несколько раз подряд признавался посетителями лучшим в Европе по онлайн-голосованию.","wiki_en":"Zagreb"},{"name":"Любляна","emoji":"🐉","meta":["Словения","около 290 тыс"],"description":"Столица Словении славится зелёными набережными реки Любляницы и замком на холме над городом, а её символом издавна считается дракон. Компактный и пешеходный центр делает город одним из самых уютных в Европе.","fact":"Дракон считается символом Любляны с легендарных времён и изображён на гербе города и его мостах.","wiki_en":"Ljubljana"},{"name":"Братислава","emoji":"👀","meta":["Словакия","около 475 тыс"],"description":"Столица Словакии на берегу Дуная расположена всего в часе езды от Вены и сохранила компактный исторический центр с замком над рекой. Границы Австрии и Венгрии проходят буквально у городской черты.","fact":"Братислава — единственная в мире столица, граничащая сразу с двумя другими суверенными государствами.","wiki_en":"Bratislava"},{"name":"Белград","emoji":"⚔️","meta":["Сербия","около 1,4 млн"],"description":"Столица Сербии стоит на слиянии рек Дунай и Сава и на протяжении истории десятки раз подвергалась разрушениям и восстанавливалась заново. Крепость Калемегдан на холме над реками — главный символ и старейшая часть города.","fact":"Крепость Калемегдан в Белграде за свою историю перестраивалась множеством империй, от римлян до османов и австрийцев.","wiki_en":"Belgrade"},{"name":"София","emoji":"🌹","meta":["Болгария","около 1,3 млн"],"description":"Столица Болгарии лежит у подножия горы Витоша и считается одной из старейших столиц Европы, чья история насчитывает тысячи лет. Золотые купола собора Александра Невского — главный символ города.","fact":"В центре Софии на небольшом пятачке можно увидеть памятники сразу нескольких эпох — римской, османской и социалистической.","wiki_en":"Sofia"},{"name":"Бухарест","emoji":"🏢","meta":["Румыния","около 1,8 млн"],"description":"Столицу Румынии в межвоенные годы называли маленьким Парижем за элегантную архитектуру бульваров. Здесь же находится Дворец парламента — одно из самых больших и тяжёлых административных зданий в мире.","fact":"Дворец парламента в Бухаресте считается одним из самых тяжёлых зданий в мире и уступает по объёму лишь единичным сооружениям.","wiki_en":"Bucharest"},{"name":"Варшава","emoji":"🕊️","meta":["Польша","около 1,8 млн"],"description":"Столица Польши была почти полностью разрушена во время Второй мировой войны и затем кропотливо восстановлена по старым чертежам и картинам. Символом города считается русалка Сирена, изображённая на гербе.","fact":"Исторический центр Варшавы был восстановлен после войны настолько точно, что его всё равно включили в список Всемирного наследия ЮНЕСКО.","wiki_en":"Warsaw"},{"name":"Краков","emoji":"🐉","meta":["Польша","около 780 тыс"],"description":"Бывшая столица Польши сохранила один из самых красивых средневековых центров Европы с Королевским замком Вавель на холме над Вислой. По легенде, под замком когда-то жил огнедышащий дракон.","fact":"У подножия Вавельского холма в Кракове установлена статуя дракона, которая по-настоящему выдыхает огонь для туристов.","wiki_en":"Kraków"},{"name":"Рига","emoji":"🎄","meta":["Латвия","около 600 тыс"],"description":"Столица Латвии на берегу Балтийского моря обладает одним из крупнейших собраний архитектуры модерна в Европе. По местной легенде, именно на ратушной площади Риги была наряжена первая в истории рождественская ёлка.","fact":"Рига претендует на звание города, где была установлена самая первая наряженная рождественская ёлка на общественной площади.","wiki_en":"Riga"},{"name":"Таллин","emoji":"🏰","meta":["Эстония","около 440 тыс"],"description":"Столица Эстонии на берегу Финского залива сохранила один из самых цельных средневековых старых городов Европы с башнями и крепостными стенами. Сегодня Таллин также известен как один из передовых цифровых городов мира.","fact":"В Таллине была разработана технология, ставшая основой сервиса Skype, что закрепило за Эстонией репутацию цифрового пионера.","wiki_en":"Tallinn"},{"name":"Вильнюс","emoji":"⛪","meta":["Литва","около 580 тыс"],"description":"Столица Литвы обладает одним из крупнейших барочных старых городов Восточной Европы с десятками церквей разных эпох. Богемный квартал Ужупис в шутку провозгласил себя независимой республикой со своей конституцией.","fact":"Район Ужупис в Вильнюсе шутливо объявил себя отдельной республикой и даже принял собственную шуточную конституцию.","wiki_en":"Vilnius"},{"name":"Минск","emoji":"🏛️","meta":["Беларусь","около 2 млн"],"description":"Столица Беларуси была практически полностью разрушена во время Второй мировой войны и отстроена заново в стиле сталинского неоклассицизма. Широкий проспект Независимости стал главной осью просторного и зелёного города.","fact":"После войны Минск отстраивали почти с нуля, поэтому центр города выглядит как цельный ансамбль сталинской архитектуры.","wiki_en":"Minsk"},{"name":"Киев","emoji":"⛪","meta":["Украина","около 2,9 млн"],"description":"Столица Украины на берегах Днепра — один из древнейших восточнославянских городов, чья история восходит к временам Киевской Руси. Золотые купола Киево-Печерской лавры и Софийского собора видны с высоких днепровских круч.","fact":"Киево-Печерская лавра известна системой пещер-катакомб, где веками селились монахи-отшельники.","wiki_en":"Kyiv"},{"name":"Одесса","emoji":"🎭","meta":["Украина","около 1 млн"],"description":"Портовый город на берегу Чёрного моря знаменит Потёмкинской лестницей, ведущей от порта к центру, и особым ироничным чувством юмора местных жителей. Одесса издавна славится многонациональным колоритом и приморским духом.","fact":"Потёмкинская лестница в Одессе спроектирована так, что снизу видны только ступени, а сверху — только площадки, за счёт разной ширины пролётов.","wiki_en":"Odesa"},{"name":"Тбилиси","emoji":"♨️","meta":["Грузия","около 1,2 млн"],"description":"Столица Грузии раскинулась в узкой долине реки Куры и известна серными банями в старом районе Абанотубани, давшими городу его название. Канатная дорога связывает исторический центр с крепостью Нарикала на холме.","fact":"Название Тбилиси происходит от грузинского слова, означающего тёплый, — из-за местных серных источников.","wiki_en":"Tbilisi"},{"name":"Батуми","emoji":"🌊","meta":["Грузия","около 170 тыс"],"description":"Приморский курорт на берегу Чёрного моря сочетает субтропическую растительность с яркой современной архитектурой набережной. Батумский ботанический сад — один из крупнейших и старейших на Кавказе.","fact":"На набережной Батуми установлена движущаяся металлическая скульптура влюблённых, фигуры которой периодически сходятся и расходятся.","wiki_en":"Batumi"},{"name":"Ереван","emoji":"🏔️","meta":["Армения","около 1,1 млн"],"description":"Столица Армении — один из древнейших постоянно населённых городов мира, старше самого Рима. Из центра города открывается вид на библейскую гору Арарат, хотя сама она находится уже на территории соседней Турции.","fact":"Гора Арарат, главный символ Армении, прекрасно видна из Еревана, хотя формально расположена за пределами страны.","wiki_en":"Yerevan"},{"name":"Баку","emoji":"🔥","meta":["Азербайджан","около 2,3 млн"],"description":"Столица Азербайджана на берегу Каспийского моря сочетает средневековый Ичери-шехер с футуристическими небоскрёбами Flame Towers, напоминающими языки пламени. Регион издавна славился выходами природного газа, горевшего прямо из земли.","fact":"Название Азербайджана нередко связывают с персидским выражением «страна огня» — из-за естественных выходов горящего газа в окрестностях Баку.","wiki_en":"Baku"},{"name":"Алматы","emoji":"🍎","meta":["Казахстан","около 2 млн"],"description":"Бывшая столица Казахстана лежит у подножия заснеженных гор Заилийского Алатау и считается одним из мест происхождения яблони домашней. Город остаётся культурным и финансовым центром страны даже после переноса столицы в Астану.","fact":"Название Алматы связано со словом «алма» — яблоко, а окрестности города считаются одним из очагов происхождения культурной яблони.","wiki_en":"Almaty"},{"name":"Астана","emoji":"🏙️","meta":["Казахстан","около 1,3 млн"],"description":"Столица Казахстана была почти полностью отстроена заново в степи в конце 1990-х и 2000-х годах по проектам известных мировых архитекторов. Монумент Байтерек с шаром на вершине стал главным символом новой столицы.","fact":"Город несколько раз менял название — от Акмолы до Астаны, затем Нур-Султана и снова Астаны.","wiki_en":"Astana"},{"name":"Ташкент","emoji":"🕌","meta":["Узбекистан","около 2,9 млн"],"description":"Столица Узбекистана — крупнейший город Центральной Азии, восстановленный после разрушительного землетрясения 1966 года в стиле советского модернизма. Одна из старейших в регионе линий метро украшена станциями-дворцами с национальными орнаментами.","fact":"После землетрясения 1966 года на восстановление Ташкента съехались строители со всего Советского Союза, что определило облик города.","wiki_en":"Tashkent"},{"name":"Самарканд","emoji":"💠","meta":["Узбекистан","около 550 тыс"],"description":"Один из древнейших городов Центральной Азии был столицей империи Тамерлана и ключевым пунктом Великого шёлкового пути. Бирюзовые купола и мозаики площади Регистан считаются вершиной среднеазиатской архитектуры.","fact":"Площадь Регистан в Самарканде окружена тремя медресе, построенными в разные века, но составляющими единый архитектурный ансамбль.","wiki_en":"Samarkand"},{"name":"Бухара","emoji":"🕌","meta":["Узбекистан","около 280 тыс"],"description":"Древний город на Великом шёлковом пути сохранил один из самых цельных исламских исторических центров Центральной Азии с минаретами, медресе и куполами. Минарет Калян веками служил ориентиром для торговых караванов в пустыне.","fact":"По легенде, минарет Калян в Бухаре настолько впечатлил Чингисхана, что он приказал не разрушать его при взятии города.","wiki_en":"Bukhara"},{"name":"Анталья","emoji":"🏖️","meta":["Турция","около 1,3 млн"],"description":"Курортный город на средиземноморском побережье Турции — один из главных туристических центров страны с песчаными пляжами и старинной гаванью Калеичи. Неподалёку от города сохранились античные руины древних греческих и римских городов.","fact":"Ворота Адриана в старом городе Антальи были построены в честь визита римского императора Адриана почти две тысячи лет назад.","wiki_en":"Antalya"},{"name":"Казань","emoji":"🐉","meta":["Россия","около 1,3 млн"],"description":"Столица Татарстана на слиянии Волги и Казанки сочетает православные соборы с минаретами мечети Кул-Шариф внутри древнего кремля. Легендарный крылатый змей Зилант считается символом города.","fact":"Мечеть Кул-Шариф и православный Благовещенский собор стоят рядом на территории одного Казанского кремля.","wiki_en":"Kazan"},{"name":"Сочи","emoji":"🏔️","meta":["Россия","около 440 тыс"],"description":"Курортный город на черноморском побережье России сочетает субтропические пляжи с горнолыжными склонами Красной Поляны неподалёку. В 2014 году Сочи принимал зимние Олимпийские игры.","fact":"Сочи стал самым тёплым городом в истории зимних Олимпийских игр — соревнования шли в субтропиках у самого моря.","wiki_en":"Sochi"},{"name":"Екатеринбург","emoji":"💎","meta":["Россия","около 1,5 млн"],"description":"Крупный промышленный город на Урале расположен почти на условной границе Европы и Азии, отмеченной специальным обелиском неподалёку. Город основан как горнозаводской центр и долгое время был важен для добычи и обработки камня.","fact":"Рядом с Екатеринбургом установлен обелиск, отмечающий условную границу между Европой и Азией.","wiki_en":"Yekaterinburg"},{"name":"Новосибирск","emoji":"🚂","meta":["Россия","около 1,6 млн"],"description":"Крупнейший город Сибири вырос из посёлка при строительстве моста через Обь для Транссибирской магистрали в конце XIX века. Сегодня это главный научный и деловой центр региона с крупным Академгородком.","fact":"Новосибирск основан благодаря строительству железнодорожного моста через Обь для Транссибирской магистрали.","wiki_en":"Novosibirsk"},{"name":"Нижний Новгород","emoji":"🏰","meta":["Россия","около 1,2 млн"],"description":"Город на слиянии Волги и Оки веками был важнейшим торговым центром России благодаря крупнейшей в стране ярмарке. Нижегородский кремль на высоком берегу считается одним из самых мощных в стране.","fact":"Нижегородская ярмарка в XIX веке была одной из крупнейших торговых ярмарок мира и во многом определяла торговые цены по всей России.","wiki_en":"Nizhny Novgorod"},{"name":"Калининград","emoji":"🏰","meta":["Россия","около 490 тыс"],"description":"Самый западный крупный город России, прежде носивший немецкое название Кёнигсберг, был передан СССР после Второй мировой войны. Регион вокруг города — крупнейший в мире источник добычи янтаря.","fact":"Побережье Калининградской области содержит крупнейшие в мире разведанные запасы янтаря.","wiki_en":"Kaliningrad"},{"name":"Владивосток","emoji":"🌉","meta":["Россия","около 600 тыс"],"description":"Главный российский порт на Тихом океане служит восточной конечной точкой Транссибирской магистрали, протянувшейся через всю страну. Вантовый мост через пролив Босфор Восточный — один из символов современного города.","fact":"Владивосток расположен ближе к Токио и Сеулу, чем к Москве, до которой почти девять тысяч километров по Транссибу.","wiki_en":"Vladivostok"},{"name":"Иркутск","emoji":"🌊","meta":["Россия","около 620 тыс"],"description":"Старинный сибирский город на реке Ангаре служит главными воротами к озеру Байкал — крупнейшему по объёму пресноводному озеру планеты. В XIX веке город стал местом ссылки декабристов, что оставило заметный след в его культуре.","fact":"Иркутск часто называют воротами Байкала — крупнейшего в мире хранилища пресной воды по объёму.","wiki_en":"Irkutsk"},{"name":"Перт","emoji":"🦢","meta":["Австралия","около 2,1 млн"],"description":"Столица Западной Австралии считается одним из самых изолированных крупных городов мира — ближайший другой мегаполис находится в тысячах километров. Чёрный лебедь, впервые описанный европейцами именно здесь, стал символом города и штата.","fact":"Перт нередко называют одним из самых удалённых от других крупных городов мегаполисов в мире.","wiki_en":"Perth, Western Australia"},{"name":"Брисбен","emoji":"☀️","meta":["Австралия","около 2,6 млн"],"description":"Столица штата Квинсленд на реке Брисбен известна тёплым субтропическим климатом и статусом ворот к пляжам Голд-Коста и Саншайн-Коста. Город готовится принять летние Олимпийские игры 2032 года.","fact":"Брисбен станет столицей летних Олимпийских игр 2032 года — третьих Олимпийских игр в истории Австралии.","wiki_en":"Brisbane"}];
